param([Parameter(Mandatory)][string]$SourceRoot,[Parameter(Mandatory)][string]$Destination)
$ErrorActionPreference='Stop'
$SourceRoot=(Resolve-Path $SourceRoot).Path
if(Test-Path $Destination){throw 'Require fresh destination'}
# Reuse unchanged XAML extraction/manifest mechanics, then replace this owned identity.
& "$PSScriptRoot/../harness-50-53/prepare.ps1" -SourceRoot $SourceRoot -Destination $Destination
Copy-Item "$PSScriptRoot/*.cs","$PSScriptRoot/*.xaml","$PSScriptRoot/Harness.csproj" $Destination -Force
$ui="$SourceRoot/src/Desktop/BiliCopilot.UI"
Copy-Item "$ui/Pages/PopularPage.xaml","$ui/Controls/Popular/PopularMainHeader.xaml","$ui/Controls/Popular/PopularSideHeader.xaml" $Destination
$manifest=Get-Content "$Destination/Package.appxmanifest" -Raw
$manifest.Replace('BiliCopilot.Acceptance5053D26C','BiliCopilot.Cache56F577').Replace('Offline Popular acceptance 50 53','Synthetic cache observation 56') | Set-Content "$Destination/Package.appxmanifest"
# StringNames is normally generated by the application build; enumerate all linked names.
$names=Get-ChildItem "$ui/ViewModels/Items/VideoItemViewModel","$ui/ViewModels/View/PopularPageViewModel","$ui/Controls/Popular","$ui/Controls/Components/VideoCardControl" -File -Recurse | Select-String 'StringNames\.([A-Za-z0-9_]+)' -AllMatches | ForEach-Object {$_.Matches.Groups | Where-Object Name -eq 1 | ForEach-Object Value}
$xnames=Get-ChildItem "$Destination/*.xaml"|Select-String 'Name=([A-Za-z0-9_]+)' -AllMatches|ForEach-Object {$_.Matches.Groups|Where-Object Name -eq 1|ForEach-Object Value}
"namespace BiliCopilot.UI.Models.Constants {public enum StringNames {$(($names+$xnames|Sort-Object -Unique)-join ',')}}"|Set-Content "$Destination/Strings.cs"
$files=@(Get-ChildItem "$ui/ViewModels/View/PopularPageViewModel","$ui/ViewModels/Items/VideoItemViewModel" -File)
$files+=Get-Item "$ui/Pages/PopularPage.xaml*","$ui/Controls/Popular/*.cs","$ui/Controls/Popular/*.xaml","$ui/Controls/IncrementVerticalScrollControl.xaml*","$ui/Controls/Components/VideoCardControl/*","$ui/Controls/BasicCoverImage.cs","$ui/Extensions/BasicScaleEffect.cs"
$files|Get-FileHash|ConvertTo-Json|Set-Content "$Destination/production-hashes.json"
Get-ChildItem "$Destination/*.xaml","$Destination/Assets/*"|Get-FileHash|ConvertTo-Json|Set-Content "$Destination/fixture-hashes.json"
